CREATE TABLE users (
  id BIGINT PRIMARY KEY,
  email TEXT UNIQUE NOT NULL
);
CREATE TABLE orders (
  id BIGINT PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  total_cents INT NOT NULL CHECK (total_cents >= 0)
  -- Integrity lives HERE. Bad user_id or negative total is rejected
  -- before commit. Readers can trust the shape.
);
